// One asset's jobs in, one summary out. Jobs are independent, so a mixed
// result is normal and must not be collapsed into a single pass/fail.
const jobs = $input.all().map((i) => i.json);
const failed = jobs.filter((j) => j.state === 'failed');
const pending = jobs.filter((j) => !['published', 'failed'].includes(j.state));

return [{
  json: {
    ok: failed.length === 0,
    published: jobs.filter((j) => j.state === 'published').map((j) => j.platform),
    failed: failed.map((j) => ({ platform: j.platform, error: j.last_error })),
    still_running: pending.map((j) => j.platform),
    summary: `${jobs.length - failed.length - pending.length}/${jobs.length} published`
      + (failed.length ? `, ${failed.length} failed: ` + failed.map((j) => `${j.platform} — ${j.last_error}`).join('; ') : '')
      + (pending.length ? `, ${pending.length} still running` : ''),
  },
}];

// Either no slot came due (the normal case, most ticks) or one came due
// with an empty backlog. Only the second is worth telling anyone about:
// a slot firing into an empty backlog looks exactly like a switched-off
// workflow from the outside.
const tick = $input.first().json;
const idle = tick.idle_slots || [];

return [{
  json: {
    ok: idle.length === 0,
    notify: idle.length > 0,
    summary: idle.length
      ? `${idle.join(', ')} came due with an empty backlog — nothing was posted.`
      : 'No slot due on this tick.',
  },
}];
